function detailModel(section,item){
 if(item==='Connectivity')return {lead:'Offline · Bluetooth '+(phoneState.bluetooth?'On':'Off'),rows:['Bluetooth: '+(phoneState.bluetooth?'On':'Off'),'Packet data: '+phoneState.packetData,'USB data cable: '+phoneState.usbMode,'Network status']};
 if(item==='Security')return {lead:'Security · '+phoneState.securityLevel,rows:['PIN code request: '+(phoneState.pinRequest?'On':'Off'),'Security level','Access codes','Certificates']};
 if(item==='Radio')return {...endpointModels.Radio,lead:'FM '+phoneState.radioFrequency+' MHz · offline',rows:['Set frequency','Stations','Search stations','Switch off']};
 if(item==='Equaliser')return {...endpointModels.Equaliser,lead:phoneState.equaliser+' · active',rows:['Normal','Pop','Rock','Jazz']};
 if(item==='Lights')return {lead:'Display light · level '+phoneState.lightLevel,rows:['Display light','Keypad light','Notifications','Restore default']};
 if(item==='Display')return {lead:phoneState.theme+' · '+phoneState.fontColour,rows:['Wallpaper: '+phoneState.wallpaper,'Home screen: '+(phoneState.homeScreen?'On':'Off'),'Font colour','Main menu view']};
 if(item==='Date and time')return {kind:'time',lead:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:!phoneState.clock24})+' · '+(phoneState.clock24?'24-hour':'12-hour'),rows:['Date & time settings','Date & time format','Auto-update: '+(phoneState.autoTime?'On':'Off'),'Time zone']};
 if(item==='Last web address')return {kind:'offline',lead:phoneState.addressHistory.length?'Stored offline':'No local address history',rows:phoneState.addressHistory.length?phoneState.addressHistory.concat(['Clear history']):['No addresses','Go to address','Settings','Help']};
 if(item==='Calendar')return {kind:'content',lead:phoneState.calendar.length?phoneState.calendar.length+' local calendar note(s)':'Today · No calendar notes',rows:phoneState.calendar.length?phoneState.calendar.map(x=>x.date+' · '+(x.body||'(blank)')).concat(['Make a note']):endpointModels.Calendar.rows};
 if(item==='Notes')return {kind:'content',lead:phoneState.notes.length?phoneState.notes.length+' local note(s)':'No notes',rows:phoneState.notes.length?phoneState.notes.map((x,i)=>(i===collectionIndex?'▶ ':'')+x.body).concat(['Make a note']):['Make a note','Edit','Delete','Memory status']};
 if(item==='To-do list'){let a=phoneState.todos||[];return {kind:'content',lead:a.length?a.length+' local to-do note(s)':'No to-do notes',rows:a.length?a.map((x,i)=>(i===collectionIndex?'▶ ':'')+(x.done?'✓ ':'○ ')+x.body).concat(['Add']):['Open','Add','Delete','Go to calendar']}};
 if(item==='All calls'||item==='Dialled numbers')return {kind:'log',lead:phoneState.callLog.length?phoneState.callLog.length+' local call(s)':'No personal call records loaded',rows:phoneState.callLog.length?phoneState.callLog.map(x=>x.number+' · '+x.status).concat(['Clear list']):['View entries','Clear list','Call duration','Details']};
 if(item==='Inbox')return {...endpointModels.Inbox,lead:phoneState.messages.length?phoneState.messages.length+' local message'+(phoneState.messages.length===1?'':'s'):'No personal messages loaded'};
 if(item==='Drafts'){let a=phoneState.messages.filter(x=>x.status==='draft');return {kind:'messages',lead:a.length===1?'1 local draft':a.length+' local drafts',rows:a.length?a.map(x=>'To '+(x.to||'(none)')+' · '+(x.body||'(blank)')).concat(['Create message']):endpointModels.Drafts.rows}};
 if(item==='Names')return {kind:'contacts',lead:phoneState.contacts.length?phoneState.contacts.length+' local contact(s)':'No contacts saved',rows:phoneState.contacts.length?phoneState.contacts.map(c=>c.name+' · '+c.number).concat(['Add']):['List','Add','Search','Options']};
 if(item==='Profiles')return {...endpointModels.Profiles,lead:phoneState.profile+' · active'};
 if(item==='Themes')return {...endpointModels.Themes,lead:phoneState.theme+' · active'};
 if(item==='Tones')return {...endpointModels.Tones,lead:'Ringing tone · '+phoneState.ringtone};
 if(item==='Alarm clock')return {...endpointModels['Alarm clock'],lead:phoneState.alarm+' · '+(phoneState.alarmEnabled?'On':'Off'),rows:['Alarm: '+(phoneState.alarmEnabled?'On':'Off'),'Alarm time','Repeat','Alarm tone']};
 if(endpointModels[item])return endpointModels[item];
 const low=item.toLowerCase();let lead=`${item} UI reference surface from the ${section} menu.`,rows=['Open','Status','Settings','Help'],kind='generic';
 if(/contact|names|numbers|groups|dial/.test(low)){rows=['List','Add','Search','Options'];lead='Contacts reference surface. No personal records are loaded.';kind='contacts'}
 else if(/message|mailbox|sent|outbox|saved/.test(low)){rows=['Open list','Create','Search','Message settings'];lead='Messaging reference surface. Message content is local test data only.';kind='messages'}
 else if(/setting|shortcut|sync|backup|call|phone|accessor|configuration|restore/.test(low)){rows=['Current value','Change','Open','Restore default'];lead='Settings reference surface. Changes stay inside this offline phone.';kind='settings'}
 else if(/photo|gallery|download|application|memory/.test(low)){rows=['Open folder','Items','Memory status','Options'];lead='Content reference surface generated from the firmware menu route.';kind='content'}
 else if(/call|log|timer|counter|recipient/.test(low)){rows=['View entries','Clear list','Duration','Details'];lead='Log reference surface. No personal call records are used.';kind='log'}
 else if(/browser|ovi|nokia|web|cache|operator/.test(low)){rows=['Open reference','Address','Bookmarks','Settings'];lead='Offline web/service reference. No retired service is contacted.';kind='offline'}
 return {lead,rows,kind};
}
