const phoneDefaults={profile:'General',theme:'Black',ringtone:'Nokia tune',volume:5,alarm:'07:00',alarmEnabled:false,clock24:true,autoTime:false,fontColour:'Automatic',homeScreen:true,wallpaper:'Theme default',lightLevel:3,equaliser:'Normal',radioFrequency:'99.5',pinRequest:false,securityLevel:'None',bluetooth:false,packetData:'When needed',usbMode:'Ask on connection',menuMode:'labelgrid',notes:[],todos:[],contacts:[],messages:[],calendar:[],callLog:[],addressHistory:[]};
